#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("USAGE\n");
        return 0;
    }
    if (strcmp(argv[1], "to_camel") == 0) {
        // to_camel logic
        int i = 0;
        int j = 0;
        char *str = argv[2];
        char out[1000];
        while (str[i] != '\0') {
            if (str[i] == '_') {
                i++;
                out[j] = toupper(str[i]);
                j++;
            } else {
                out[j] = str[i];
                j++;
            }
            i++;
        }
        out[j] = '\0';
        printf("%s\n", out);
    } else if (strcmp(argv[1], "to_snake") == 0) {
        // to_snake logic
        int i = 0;
        int j = 0;
        char *str = argv[2];
        char out[1000];
        while (str[i] != '\0') {
            if (isupper(str[i])) {
                out[j] = '_';
                j++;
                out[j] = tolower(str[i]);
                j++;
            } else {
                out[j] = str[i];
                j++;
            }
            i++;
        }
        out[j] = '\0';
        printf("%s\n", out);
    } else {
        printf("INVALID_MODE\n");
    }
    return 0;
}
